# Load all available demos and grids so far
import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("All available input grids:")
for k in sorted(G.keys()):
    print(f"  {k}: {G[k].shape if hasattr(G[k], 'shape') else 'list'}")

# Theory: 0s shift down one row, staying in the same column
# Other values (8 in demo) stay the same

def transform_shift_down(grid):
    result = []
    for row in grid:
        result.append(row)  # Start with same row
    # Apply the shift: move 0s down
    rows = len(grid)
    cols = len(grid[0]) if grid else 0

    # Create a tracker for where 0s go
    new_shift = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                new_shift[(r + 1) % rows][c] = 1  # Mark that a 0 should be here

    return new_shift

